CREATE OR REPLACE FUNCTION public.cellar_move_ok(p_world uuid, p_uid uuid, p_from integer, p_to integer, p_fx double precision, p_fy double precision, p_x double precision, p_y double precision)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_fx int := floor(p_fx)::int; v_fy int := floor(p_fy)::int; v_x int := floor(p_x)::int; v_y int := floor(p_y)::int;
        c cellar_tile; f floor_tile;
begin
  if p_to >= 0 and p_from >= 0 then return true; end if;
  if p_to < 0 then
